/** Worker-only, best-effort storage for calibrated best-image admission tiles.
 * No scene objects or full catalogs cross the IndexedDB boundary. */
const DATABASE = "carma-best-image-axis-cells-v1";
const STORE = "cells";
const MAX_STORED_BYTES = 64 * 1024 * 1024;
// SHA-256 round constants. The pure-JS path is needed by Workers served from
// private HTTP LAN addresses, where WebCrypto's subtle API is unavailable.
const SHA256_K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1,
  0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786,
  0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b,
  0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
  0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);
const rotate = (word: number, bits: number) =>
  (word >>> bits) | (word << (32 - bits));
const sha256Fallback = (input: Uint8Array) => {
  const paddedLength = Math.ceil((input.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  padded.set(input);
  padded[input.length] = 0x80;
  const view = new DataView(padded.buffer);
  const bitLength = input.length * 8;
  view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
  view.setUint32(paddedLength - 4, bitLength >>> 0);
  const state = new Uint32Array([
    0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c,
    0x1f83d9ab, 0x5be0cd19,
  ]);
  const words = new Uint32Array(64);
  for (let offset = 0; offset < paddedLength; offset += 64) {
    for (let at = 0; at < 16; at++) words[at] = view.getUint32(offset + at * 4);
    for (let at = 16; at < 64; at++) {
      const a = words[at - 15],
        b = words[at - 2];
      const s0 = rotate(a, 7) ^ rotate(a, 18) ^ (a >>> 3);
      const s1 = rotate(b, 17) ^ rotate(b, 19) ^ (b >>> 10);
      words[at] = (words[at - 16] + s0 + words[at - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = state;
    for (let at = 0; at < 64; at++) {
      const s1 = rotate(e, 6) ^ rotate(e, 11) ^ rotate(e, 25);
      const choose = (e & f) ^ (~e & g);
      const first = (h + s1 + choose + SHA256_K[at] + words[at]) >>> 0;
      const s0 = rotate(a, 2) ^ rotate(a, 13) ^ rotate(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const second = (s0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + first) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (first + second) >>> 0;
    }
    state[0] = (state[0] + a) >>> 0;
    state[1] = (state[1] + b) >>> 0;
    state[2] = (state[2] + c) >>> 0;
    state[3] = (state[3] + d) >>> 0;
    state[4] = (state[4] + e) >>> 0;
    state[5] = (state[5] + f) >>> 0;
    state[6] = (state[6] + g) >>> 0;
    state[7] = (state[7] + h) >>> 0;
  }
  return Array.from(state, (word) => word.toString(16).padStart(8, "0")).join(
    ""
  );
};
type StoredCell = {
  key: string;
  indices: Uint32Array;
  bytes: number;
  savedAt: number;
};

let database: Promise<IDBDatabase | null> | undefined;
const open = () => {
  database ??= new Promise((resolve) => {
    if (typeof indexedDB === "undefined") return resolve(null);
    try {
      const request = indexedDB.open(DATABASE, 1);
      request.onupgradeneeded = () => {
        const store = request.result.createObjectStore(STORE, {
          keyPath: "key",
        });
        store.createIndex("savedAt", "savedAt");
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => resolve(null);
      request.onblocked = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
  return database;
};

export const readAxisCell = async (key: string, sourceCount: number) => {
  const db = await open();
  if (!db) return null;
  return new Promise<Uint32Array | null>((resolve) => {
    try {
      const request = db
        .transaction(STORE, "readonly")
        .objectStore(STORE)
        .get(key);
      request.onsuccess = () => {
        const value = request.result as StoredCell | undefined;
        const indices = value?.indices;
        if (!(indices instanceof Uint32Array)) return resolve(null);
        for (let at = 0; at < indices.length; at++)
          if (
            indices[at] >= sourceCount ||
            (at && indices[at] <= indices[at - 1])
          )
            return resolve(null);
        resolve(indices);
      };
      request.onerror = () => resolve(null);
    } catch {
      resolve(null);
    }
  });
};

let writes = 0;
const trim = async (db: IDBDatabase) => {
  // Infrequent cursor sweep keeps the origin cache bounded without blocking
  // foreground queries or serializing cell tables on the UI thread.
  await new Promise<void>((resolve) => {
    try {
      const tx = db.transaction(STORE, "readwrite");
      const store = tx.objectStore(STORE);
      const rows: { key: string; bytes: number }[] = [];
      let total = 0;
      const cursor = store.index("savedAt").openCursor();
      cursor.onsuccess = () => {
        const item = cursor.result;
        if (!item) {
          for (const row of rows) {
            if (total <= MAX_STORED_BYTES) break;
            store.delete(row.key);
            total -= row.bytes;
          }
          return;
        }
        const value = item.value as StoredCell;
        const bytes = Number.isFinite(value.bytes) ? value.bytes : 0;
        rows.push({ key: value.key, bytes });
        total += bytes;
        item.continue();
      };
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
      tx.onabort = () => resolve();
    } catch {
      resolve();
    }
  });
};

export const writeAxisCell = async (key: string, indices: Uint32Array) => {
  const db = await open();
  if (!db || indices.byteLength > MAX_STORED_BYTES) return;
  await new Promise<void>((resolve) => {
    try {
      const tx = db.transaction(STORE, "readwrite");
      tx.objectStore(STORE).put({
        key,
        indices,
        bytes: indices.byteLength,
        savedAt: Date.now(),
      } satisfies StoredCell);
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve();
      tx.onabort = () => resolve();
    } catch {
      resolve();
    }
  });
  if (++writes % 64 === 0) void trim(db);
};

export const axisCellGeometryKey = async (
  namespace: string | undefined,
  geometry: Float64Array,
  cellSizeMeters: number
) => {
  if (!namespace) return null;
  try {
    const bytes = new Uint8Array(
      geometry.buffer,
      geometry.byteOffset,
      geometry.byteLength
    );
    let hex: string;
    const subtle = globalThis.crypto?.subtle;
    if (subtle) {
      try {
        hex = Array.from(
          new Uint8Array(await subtle.digest("SHA-256", bytes)),
          (byte) => byte.toString(16).padStart(2, "0")
        ).join("");
      } catch {
        hex = sha256Fallback(bytes);
      }
    } else hex = sha256Fallback(bytes);
    return `${namespace}|${cellSizeMeters}|${hex}`;
  } catch {
    return null;
  }
};
